import json,hashlib,datetime
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
p='eval-log/run-dev-graph-node-progress.json'; pr=json.load(open(p))
pr['updated_at']=now; pr['overall']='PASS'
pr['writer_receipts']=['.dev-graph/state/receipts/node-r000001-add.json']
ev={'classification':'add receipt node-r000001-add.json: decision auto, spec 0.95/margin 0.65, arch 0.92/margin 0.57 (>=0.80, >=0.15)',
 'schema':'writer pre_write_validation findings=0; validate-graph-schema --strict-artifact-readiness exit0 valid=true (R3-import/schema-report.json)',
 'receipt':'receipt graph_revision 0->1, node_ids [spec-billing-audit-system-spec, arch-billing-audit-system-architecture] match graph; graph_digest_after sha256:857ed57f… = current graph'}
for c in pr['checklist']:
  if c['id'] in ev: c.update(status='achieved',evidence=ev[c['id']])
pr['feedback_criteria'][0].update(status='PASS',evidence='validate-graph-schema pre-write findings=0 and post-commit strict exit0')
pr['independent_verifier']={'agent':'dev-graph:dev-graph-integrity-auditor','verdict':'PASS','graph_digest':'sha256:857ed57f6a41eea72add76f819a1b5240b8d63ed6875e3bf86ce99594f0eeab0'}
json.dump(pr,open(p,'w'),ensure_ascii=False,indent=2)
g=json.load(open('eval-log/run-dev-graph-node-goal-spec.json'))
row={'loop':1,'at':now,'original_goal':g['original_goal'],'original_goal_hash':hashlib.sha256(g['original_goal'].encode()).hexdigest(),
'current_goal_snapshot':'specification/architecture 2 node を C02 add で atomic 登録 (rev 1)、integrity auditor PASS',
'delta_from_original':'none for this invocation (package/feature 対象外)','merged_directive_for_next':'none: return receipt to C19 R3','drift_signal':'none'}
open('eval-log/run-dev-graph-node-intermediate.jsonl','a').write(json.dumps(row,ensure_ascii=False)+'\n')
PY
python3 - "$CLAUDE_PROJECT_DIR/eval-log/run-dev-graph-node-goal-spec.json" "$CLAUDE_PROJECT_DIR/eval-log/run-dev-graph-node-intermediate.jsonl" "$CLAUDE_PROJECT_DIR/eval-log/run-dev-graph-node-progress.json" "$CLAUDE_PROJECT_DIR/.dev-graph/state/graph.json" "$CLAUDE_PROJECT_DIR" <<'PY'
import hashlib, json, os, sys
goal = json.load(open(sys.argv[1], encoding='utf-8'))
rows = [json.loads(line) for line in open(sys.argv[2], encoding='utf-8') if line.strip()]
progress = json.load(open(sys.argv[3], encoding='utf-8'))
graph = json.load(open(sys.argv[4], encoding='utf-8'))
required_keys = {'original_goal','original_goal_hash','current_goal_snapshot','delta_from_original','merged_directive_for_next','drift_signal'}
expected = hashlib.sha256(goal['original_goal'].encode('utf-8')).hexdigest()
assert rows
for row in rows:
    assert required_keys <= row.keys(); assert row['original_goal'] == goal['original_goal']; assert row['original_goal_hash'] == expected
digest = 'sha256:' + hashlib.sha256(json.dumps(graph, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
receipts = [json.load(open(os.path.join(sys.argv[5], p), encoding='utf-8')) for p in progress.get('writer_receipts') or []]
baseline = progress.get('graph_baseline') or {}
revisions = [baseline.get('graph_revision')] + [r.get('graph_revision_after') for r in receipts]
assert all(r.get('graph_revision_before') == before for r, before in zip(receipts, revisions))
last = (receipts[-1].get('graph_revision_after'), receipts[-1].get('graph_digest_after')) if receipts else (baseline.get('graph_revision'), baseline.get('graph_digest'))
assert last == (graph.get('graph_revision'), digest), last
verifier = progress.get('independent_verifier') or {}
assert verifier.get('agent') in {'dev-graph-integrity-auditor', 'dev-graph:dev-graph-integrity-auditor'}
assert verifier.get('graph_digest') == digest
def entries(value):
    pairs = list(value.items() if isinstance(value, dict) else ((c.get('id'), c) for c in value))
    out = {cid: (c if isinstance(c, dict) else {'status': c}) for cid, c in pairs}
    assert len(out) == len(pairs); return out
status = {cid: c.get('status') for cid, c in entries(progress.get('feedback_criteria') or {}).items()}
assert set(status) == {'IN1','OUT1','OUT2','OUT3'}
assert set(v for k,v in status.items() if k!='IN1') == {'external_pending'}
checklist = entries(progress.get('checklist') or {})
assert set(checklist) == {'containment','classification','schema','package','receipt'}
na = {cid for cid, c in checklist.items() if c.get('status') == 'not_applicable'}
classified = any(r.get('operation') == 'add' and any((a.get('classification') or {}).get('decision') != 'c14_macro_contract' for a in r.get('artifacts') or []) for r in receipts)
required = {'receipt'} if receipts else set()
required |= {'package'} if any('feature_package_id' in r for r in receipts) else set()
required |= {'classification'} if classified else set()
assert not (na & required), na & required
if progress['overall'] == 'PASS':
    assert verifier['verdict'] == 'PASS' and status['IN1'] == 'PASS' and all(c['status'] != 'not_achieved' for c in checklist.values())
print('C02 goal-seek check OK', digest)
PY

